// === Tab: mySketch ===
let shapes = [];
let currentShape;
let nextShape;
let morphAmount = 2;
let framesPerShape = 60; // Number of frames for each shape transition

let osc;
let playing = false;

function setup() {
  createCanvas(400, 400, WEBGL);
  shapes.push(new SphereShape());
  shapes.push(new ConeShape());
  shapes.push(new CylinderShape());
  shapes.push(new TorusShape());
  shapes.push(new CubeShape());
  shapes.push(new OctahedronShape());

  currentShape = random(shapes);
  nextShape = random(shapes);

  // Create oscillator for sound
  osc = new p5.Oscillator();
  osc.setType('sine'); // Set the waveform type (sine, triangle, sawtooth, square)
  osc.start();
  osc.amp(0); // Set initial volume to 0
}

function draw() {
  background(220);
  orbitControl(); // Enable mouse control

  morphAmount += 1 / framesPerShape;

  if (morphAmount > 1) {
    currentShape = nextShape;
    nextShape = random(shapes);
    morphAmount = 0;

    // Play a random note when the shape morphs
    playRandomNote();
  }

  let currentVertices = currentShape.getVertices();
  let nextVertices = nextShape.getVertices();
  let lerpedVertices = [];

  for (let i = 0; i < currentVertices.length; i++) {
    let lerpedVertex = p5.Vector.lerp(currentVertices[i], nextVertices[i], morphAmount);
    lerpedVertices.push(lerpedVertex);
  }

  let color1 = currentShape.getColor();
  let color2 = nextShape.getColor();
  let lerpedColor = lerpColor(color1, color2, morphAmount);

  fill(lerpedColor);
  stroke(0);
  beginShape();
  for (let i = 0; i < lerpedVertices.length; i++) {
    vertex(lerpedVertices[i].x * 150, lerpedVertices[i].y * 150, lerpedVertices[i].z * 150);
  }
  endShape(CLOSE);
}

function playRandomNote() {
  let freq = random(50, 1000); // Random frequency between 50 Hz and 1000 Hz
  osc.freq(freq);
  osc.amp(0.7, 0.1); // Set volume to 0.5 with a ramp time of 0.1 seconds
  setTimeout(() => osc.amp(0, 0.1), 100); // Fade out after 100 milliseconds
}

class SphereShape {
  constructor() {
    this.vertices = this.createVertices(40);
    this.color = randomColor();
  }

  createVertices(resolution) {
    let vertices = [];
    for (let lat = 0; lat <= resolution; lat++) {
      let theta = map(lat, 0, resolution, 0, PI);
      for (let lon = 0; lon <= resolution; lon++) {
        let phi = map(lon, 0, resolution, 0, TWO_PI);
        let x = sin(theta) * cos(phi);
        let y = sin(theta) * sin(phi);
        let z = cos(theta);
        vertices.push(createVector(x, y, z));
      }
    }
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

class ConeShape {
  constructor() {
    this.vertices = this.createVertices(30);
    this.color = randomColor();
  }

  createVertices(resolution) {
    var vertices = [];
    vertices.push(createVector(0, 1, 0)); // Apex
    for (let i = 0; i <= resolution; i++) {
      let angle = map(i, 0, resolution, 0, TWO_PI);
      var x = cos(angle);
      var y = -1; // Base at y = -1
      var z = sin(angle);
      vertices.push(createVector(x, y, z));
    }
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

class CylinderShape {
  constructor() {
    this.vertices = this.createVertices(30);
    this.color = randomColor();
  }

  createVertices(resolution) {
    var vertices = [];
    for (let i = 0; i <= resolution; i++) {
      var angle = map(i, 0, resolution, 0, TWO_PI);
      var x = cos(angle);
      var z = sin(angle);
      vertices.push(createVector(x, -1, z)); // Base 1 at y = -1
      vertices.push(createVector(x, 1, z));  // Base 2 at y = 1
    }
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

class TorusShape {
  constructor() {
    this.vertices = this.createVertices(40, 10);
    this.color = randomColor();
  }

  createVertices(resolution1, resolution2) {
    var vertices = [];
    for (let i = 0; i <= resolution1; i++) {
      let angle1 = map(i, 0, resolution1, 0, TWO_PI);
      for (let j = 0; j <= resolution2; j++) {
        let angle2 = map(j, 0, resolution2, 0, TWO_PI);
        var x = (1 + 0.5 * cos(angle1)) * cos(angle2);
        var y = (1 + 0.5 * cos(angle1)) * sin(angle2);
        var z = 0.5 * sin(angle1);
        vertices.push(createVector(x, y, z));
      }
    }
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

class CubeShape {
  constructor() {
    this.vertices = this.createVertices();
    this.color = randomColor();
  }

  createVertices() {
    var vertices = [];
    let side = 4;
    for (let i = -1; i <= 1; i += 2) {
      for (let j = -1; j <= 1; j += 2) {
        for (let k = -1; k <= 1; k += 2) {
          vertices.push(createVector(i * side / 2, j * side / 2, k * side / 2));
        }
      }
    }
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

class OctahedronShape {
  constructor() {
    this.vertices = this.createVertices();
    this.color = randomColor();
  }

  createVertices() {
    var vertices = [
      createVector(1, 0, 0),
      createVector(-1, 0, 0),
      createVector(0, 1, 0),
      createVector(0, -1, 0),
      createVector(0, 0, 1),
      createVector(0, 0, -1)
    ];
    return vertices;
  }

  getVertices() {
    return this.vertices;
  }

  getColor() {
    return this.color;
  }
}

function randomColor() {
  let colors = [color('green'), color('blue'), color('red'), color('yellow'), color('gold'), color('brown')];
  return random(colors);
}

